from pkg_resources import working_set

def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Return a dictionary mapping each given distribution name to its installed version string or None if not installed.

    The lookup is case-insensitive but the keys in the returned dict preserve the original casing.
    """
    # Create a mapping of lowercase distribution names to their version strings
    installed = {dist.project_name.lower(): dist.version for dist in working_set}
    result = {}
    for name in names:
        version = installed.get(name.lower())
        result[name] = version
    return result

