import pkg_resources


def dependency_report(names: list[str]) -> dict[str, Optional[str]]:
    """Return a dict mapping each given distribution name to its installed version string or None if not installed.

    The matching is case-insensitive but keys in the returned dict preserve the input case.
    """
    # Build a mapping of lower-case distribution names to their version strings
    installed_versions = {
        dist.project_name.lower(): dist.version for dist in pkg_resources.working_set
    }

    result: dict[str, Optional[str]] = {}
    for name in names:
        version = installed_versions.get(name.lower())
        result[name] = version

    return result

from marshmallow import Schema, fields, validates, ValidationError


class SignupSchema(Schema):
    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer(required=False)

    @validates("username")
    def validate_username(self, value: str) -> None:
