        raise err
    return result

from importlib.metadata import version, PackageNotFoundError

def dependency_report(names: list[str]) -> dict[str, str | None]:
    result: dict[str, str | None] = {}
    for name in names:
        try:
            ver = version(name)
        except PackageNotFoundError:
            ver = None
        result[name] = ver
    return result

